-- ---------- enum rol_usuario ----------
DO $$ BEGIN
  CREATE TYPE rol_usuario AS ENUM ('estudiante', 'monitor', 'admin');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ---------- enum tipo_activo ----------
DO $$ BEGIN
  CREATE TYPE tipo_activo AS ENUM ('trazable', 'consumible');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ---------- enum estado_activo ----------
DO $$ BEGIN
  CREATE TYPE estado_activo AS ENUM ('disponible', 'prestado', 'dañado', 'mantenimiento', 'incompleto');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ---------- enum estado_prestamo ----------
DO $$ BEGIN
  CREATE TYPE estado_prestamo AS ENUM ('pendiente', 'activo', 'devuelto', 'rechazado', 'mora');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ---------- areas ----------
CREATE TABLE IF NOT EXISTS public.areas (
  "id_area" uuid NOT NULL DEFAULT gen_random_uuid(),
  "nombre_area" text NOT NULL,
  "descripcion" text,
  PRIMARY KEY ("id_area"),
  UNIQUE (nombre_area)
);

-- ---------- categorias ----------
CREATE TABLE IF NOT EXISTS public.categorias (
  "id_categoria" uuid NOT NULL DEFAULT gen_random_uuid(),
  "id_area" uuid NOT NULL,
  "nombre_categoria" text NOT NULL,
  "descripcion_categoria" text,
  PRIMARY KEY ("id_categoria"),
  UNIQUE (id_area, nombre_categoria),
  FOREIGN KEY (id_area) REFERENCES areas(id_area)
);

-- ---------- configuracion ----------
CREATE TABLE IF NOT EXISTS public.configuracion (
  "clave" text NOT NULL,
  "valor" text,
  PRIMARY KEY ("clave")
);

-- ---------- perfiles ----------
CREATE TABLE IF NOT EXISTS public.perfiles (
  "id_perfil" uuid NOT NULL DEFAULT gen_random_uuid(),
  "codigo_estudiantil" varchar NOT NULL,
  "cedula" varchar NOT NULL,
  "nombre_completo" text NOT NULL,
  "correo_institucional" text NOT NULL,
  "programa_academico" text,
  "telefono" varchar,
  "rol" rol_usuario DEFAULT 'estudiante'::rol_usuario,
  "wallet_address" text,
  "created_at" timestamptz DEFAULT now(),
  PRIMARY KEY ("id_perfil"),
  UNIQUE (cedula),
  UNIQUE (codigo_estudiantil),
  UNIQUE (correo_institucional)
);

-- ---------- activos ----------
CREATE TABLE IF NOT EXISTS public.activos (
  "id_activo" uuid NOT NULL DEFAULT gen_random_uuid(),
  "codigo_qr" varchar,
  "nombre_activo" text NOT NULL,
  "id_categoria" uuid,
  "id_activo_padre" uuid,
  "tipo" tipo_activo DEFAULT 'trazable'::tipo_activo,
  "estado" estado_activo DEFAULT 'disponible'::estado_activo,
  "foto_url" text,
  "observaciones_iniciales" text,
  "stock_actual" int4 DEFAULT 0,
  PRIMARY KEY ("id_activo"),
  UNIQUE (codigo_qr),
  FOREIGN KEY (id_activo_padre) REFERENCES activos(id_activo),
  FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria)
);

-- ---------- prestamos ----------
CREATE TABLE IF NOT EXISTS public.prestamos (
  "id_prestamo" uuid NOT NULL DEFAULT gen_random_uuid(),
  "id_estudiante" uuid NOT NULL,
  "id_monitor_validador" uuid,
  "fecha_inicio" timestamptz DEFAULT now(),
  "fecha_limite" timestamptz NOT NULL,
  "fecha_cierre_total" timestamptz,
  "materia" text,
  "profesor_encargado" text,
  "curso_grupo" text,
  "blockchain_hash" text,
  "estado_general" estado_prestamo DEFAULT 'activo'::estado_prestamo,
  "motivo_rechazo" text,
  "nombre_docente" text,
  PRIMARY KEY ("id_prestamo"),
  UNIQUE (blockchain_hash),
  FOREIGN KEY (id_estudiante) REFERENCES perfiles(id_perfil),
  FOREIGN KEY (id_monitor_validador) REFERENCES perfiles(id_perfil)
);

-- ---------- detalles_prestamo ----------
CREATE TABLE IF NOT EXISTS public.detalles_prestamo (
  "id_detalle" uuid NOT NULL DEFAULT gen_random_uuid(),
  "id_prestamo" uuid,
  "id_activo" uuid,
  "cantidad_entregada" int4 DEFAULT 1,
  "observacion_entrega" text,
  "observacion_devolucion" text,
  "esta_devuelto" bool DEFAULT false,
  PRIMARY KEY ("id_detalle"),
  FOREIGN KEY (id_activo) REFERENCES activos(id_activo),
  FOREIGN KEY (id_prestamo) REFERENCES prestamos(id_prestamo) ON DELETE CASCADE
);

CREATE SEQUENCE IF NOT EXISTS registro_blockchain_id_registro_seq;

-- ---------- registro_blockchain ----------
CREATE TABLE IF NOT EXISTS public.registro_blockchain (
  "id_registro" int8 NOT NULL DEFAULT nextval('registro_blockchain_id_registro_seq'::regclass),
  "tipo" varchar NOT NULL,
  "id_prestamo" uuid NOT NULL,
  "loan_hash" text NOT NULL,
  "asset_hash" text NOT NULL,
  "student_hash" text NOT NULL,
  "prev_hash" text,
  "hash_registro" text NOT NULL,
  "fecha" timestamptz DEFAULT now(),
  "id_estudiante" uuid,
  "id_monitor" uuid,
  "id_activo" uuid,
  "monitor_hash" text,
  "estado" text,
  "ubicacion" text,
  PRIMARY KEY ("id_registro"),
  UNIQUE (hash_registro),
  CHECK (((tipo)::text = ANY (ARRAY[('loan'::character varying)::text, ('return'::character varying)::text])))
);

